/* Footer */
.footer, footer {
    background: #ffffff;
    border-top: 1px solid var(--border);
    color: #64748b;
    margin-top: auto;
}

.footer-content {
    max-width: 1200px;
    margin: 0 auto;
    padding: 3rem 1.5rem;
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 1.5rem;
}

.footer-brand {
    display: flex;
    align-items: center;
    gap: 1rem;
    color: #0f172a;
}

.footer-brand .brand-title {
    color: #0f172a;
}

.footer-links {
    display: flex;
    gap: 1.5rem;
    flex-wrap: wrap;
}

.footer-links a {
    color: #64748b;
    text-decoration: none;
    font-size: 0.9rem;
    font-weight: 500;
    transition: color 0.2s;
}

.footer-links a:hover {
    color: var(--primary);
}

.footer-bottom {
    border-top: 1px solid #f1f5f9;
    padding: 1.25rem 1.5rem;
    color: #94a3b8;
    font-size: 0.85rem;
}

footer p {
    text-align: center;
    padding: 1.5rem;
    color: #64748b;
    font-size: 0.85rem;
}

/* Responsive Media Queries */
@media (max-width: 768px) {
    .hero-title {
        font-size: 2.1rem;
    }
    .input-group {
        flex-direction: column;
    }
    .nav-toggle {
        display: flex;
    }
    .nav-menu, .nav-links {
        display: none;
        flex-direction: column;
        position: absolute;
        top: 100%;
        left: 0;
        right: 0;
        background: #ffffff;
        padding: 1.5rem;
        border-bottom: 1px solid var(--border);
        box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.1);
    }
    .nav-menu.open, .nav-links.open {
        display: flex;
    }
    .ai-chat-window {
        width: calc(100vw - 2rem);
        right: -1rem;
    }
}

